class Solution {

    /**
     * @param String $s
     * @return Integer
     */
    function countPalindromicSubsequences($s) {
        $MOD = 1000000007;
        $n = strlen($s);

        // dp[i][j] = number of different palindromic subsequences in s[i..j]
        $dp = array_fill(0, $n, []);
        for ($i = 0; $i < $n; $i++) {
            $dp[$i] = array_fill(0, $n, 0);
        }

        // next and prev arrays to find next and previous occurrence of each character
        // for each position in s for characters 'a','b','c','d'
        $next = array_fill(0, $n, []);
        $prev = array_fill(0, $n, []);
        for ($i = 0; $i < $n; $i++) {
            $next[$i] = array_fill(0, 4, -1);
            $prev[$i] = array_fill(0, 4, -1);
        }
        // Map characters to indices: a->0, b->1, c->2, d->3
        $charToIndex = ['a'=>0, 'b'=>1, 'c'=>2, 'd'=>3];

        // Build prev array
        $last = [-1,-1,-1,-1];
        for ($i = 0; $i < $n; $i++) {
            $c = $charToIndex[$s[$i]];
            for ($ch = 0; $ch < 4; $ch++) {
                $prev[$i][$ch] = $last[$ch];
            }
            $last[$c] = $i;
        }
        // Build next array
        $last = [-1,-1,-1,-1];
        for ($i = $n - 1; $i >= 0; $i--) {
            $c = $charToIndex[$s[$i]];
            for ($ch = 0; $ch < 4; $ch++) {
                $next[$i][$ch] = $last[$ch];
            }
            $last[$c] = $i;
        }

        // Base cases: single letter substrings
        for ($i = 0; $i < $n; $i++) {
            $dp[$i][$i] = 1;
        }

        for ($length = 2; $length <= $n; $length++) {
            for ($i = 0; $i <= $n - $length; $i++) {
                $j = $i + $length - 1;
                $dp[$i][$j] = 0;
                // For each character 'a'..'d', count palindromes starting and ending with that character inside s[i..j]
                for ($ch = 0; $ch < 4; $ch++) {
                    $left = $next[$i][$ch];
                    $right = $prev[$j][$ch];
                    if ($left == -1 || $left > $j) {
                        // Character ch does not appear in s[i..j]
                        continue;
                    }
                    if ($left == $right) {
                        // only one occurrence of this char in s[i..j]
                        $dp[$i][$j] = ($dp[$i][$j] + 1) % $MOD;
                    } else if ($left < $right) {
                        // multiple occurrences, count palindromes inside s[left+1..right-1]
                        $dp[$i][$j] = ($dp[$i][$j] + 2 + $dp[$left+1][$right-1]) % $MOD;
                    }
                }
            }
        }

        return $dp[0][$n-1];
    }
}

